fn from_hex<'de, D: Deserializer<'de>>(d: D) -> Result<Vec<u8>, D::Error> {
    hex::decode(String::deserialize(d)?).map_err(serde::de::Error::custom)
}

fn from_hash_name<'de, D: Deserializer<'de>>(d: D) -> Result<HashingAlgorithm, D::Error> {
    match String::deserialize(d)?.as_str() {
        "SHA-1" => Ok(HashingAlgorithm::SHA1),
        "SHA-224" => Ok(HashingAlgorithm::SHA224),
        "SHA-256" => Ok(HashingAlgorithm::SHA256),
        "SHA-384" => Ok(HashingAlgorithm::SHA384),
        "SHA-512" => Ok(HashingAlgorithm::SHA512),
        "SHA3-224" => Ok(HashingAlgorithm::SHA3224),
        "SHA3-256" => Ok(HashingAlgorithm::SHA3256),
        "SHA3-384" => Ok(HashingAlgorithm::SHA3384),
        "SHA3-512" => Ok(HashingAlgorithm::SHA3512),
        other => Err(serde::de::Error::custom(format!("unknown hash {other}"))),
    }
}

fn load<T: DeserializeOwned>(file: &str) -> CryptoResult<Vec<T>> {
    let path = Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("../../test_data/vectors/kat/sources")
        .join(file);
    let vectors: Vec<T> = std::fs::read_to_string(&path)
        .map_err(|e| e.to_string())
        .and_then(|s| serde_json::from_str(&s).map_err(|e| e.to_string()))
        .map_err(|e| CryptoError::Default(format!("KAT vectors {file}: {e}")))?;
    if vectors.is_empty() {
        return Err(CryptoError::Default(format!(
            "KAT vectors {file}: no vector"
        )));
    }
    Ok(vectors)
}

